text:
{
  "table": {
    "name": "schools",
    "purpose": "California Department of Education public schools directory: one row per school/site (active, closed, merged and pending), plus a small number of district-level records (CDSCode ending in 0000000, which have null school-level fields). Keyed by the 14-digit CDS (County-District-School) code and referenced by satscores.cds (per-school SAT scores); frpm (free/reduced-price meal data) presumably joins on the same code. Holds location and mailing addresses, contacts, administrator names/emails, grade spans, CDE type/program codes, charter/magnet/virtual flags, NCES IDs and open/close dates."
  },
  "columns": {
    "AdmEmail1": {
      "role": "identifier",
      "name": "Administrator 1 email",
      "description": "Email address of the school's first listed administrator (e.g., principal/director); ~34% null, mostly records with no administrator listed.",
      "status": "resolved"
    },
    "AdmEmail2": {
      "role": "identifier",
      "name": "Administrator 2 email",
      "description": "Email address of the school's second listed administrator; populated for only ~2.4% of rows.",
      "status": "resolved"
    },
    "AdmEmail3": {
      "role": "identifier",
      "name": "Administrator 3 email",
      "description": "Email address of the school's third listed administrator; almost never populated (0.2% non-null).",
      "status": "resolved"
    },
    "AdmFName1": {
      "role": "identifier",
      "name": "Administrator 1 first name",
      "description": "First name of the school's first listed administrator; null pattern matches AdmEmail1/AdmLName1.",
      "status": "resolved"
    },
    "AdmFName2": {
      "role": "identifier",
      "name": "Administrator 2 first name",
      "description": "First name of the school's second listed administrator.",
      "status": "resolved"
    },
    "AdmFName3": {
      "role": "identifier",
      "name": "Administrator 3 first name",
      "description": "First name of the school's third listed administrator.",
      "status": "resolved"
    },
    "AdmLName1": {
      "role": "identifier",
      "name": "Administrator 1 last name",
      "description": "Last name of the school's first listed administrator.",
      "status": "resolved"
    },
    "AdmLName2": {
      "role": "identifier",
      "name": "Administrator 2 last name",
      "description": "Last name of the school's second listed administrator.",
      "status": "resolved"
    },
    "AdmLName3": {
      "role": "identifier",
      "name": "Administrator 3 last name",
      "description": "Last name of the school's third listed administrator.",
      "status": "resolved"
    },
    "CDSCode": {
      "role": "identifier",
      "name": "CDS code (primary key)",
      "description": "14-digit California County-District-School code: 2-digit county + 5-digit district + 7-digit school (trailing 0000000 marks a district-level record). Unique across all 17,686 rows; primary key; referenced one-to-one by satscores.cds.",
      "status": "resolved"
    },
    "Charter": {
      "role": "identifier",
      "name": "Charter school flag",
      "description": "1 = the school is a charter school, 0 = not; null for ~8% of rows (non-school/district-level records).",
      "status": "resolved"
    },
    "CharterNum": {
      "role": "identifier",
      "name": "Charter school number",
      "description": "State-assigned charter school number (4-character code, may contain letters, e.g. '00D2'); populated only for charter schools (~10% of rows), matching the Charter=1 count.",
      "status": "resolved"
    },
    "City": {
      "role": "identifier",
      "name": "Physical address city",
      "description": "City of the school's physical location (pairs with Street/State/Zip).",
      "status": "resolved"
    },
    "ClosedDate": {
      "role": "identifier",
      "name": "Closure date",
      "description": "Date the school was closed; null for active/pending schools. The 1989-06-30 spike (2,009 rows) looks like a batch/default closure date.",
      "status": "resolved"
    },
    "County": {
      "role": "identifier",
      "name": "County",
      "description": "Name of the California county (58 counties) in which the school is located.",
      "status": "resolved"
    },
    "DOC": {
      "role": "identifier",
      "name": "District type code (DOC)",
      "description": "Two-digit CDE code for the type of district/agency that operates the school; pairs 1:1 with DOCType (54 = Unified School District, 52 = Elementary School District, 00 = County Office of Education, 56 = High School District, 98 = Regional Occupation Center/Program).",
      "status": "resolved"
    },
    "DOCType": {
      "role": "identifier",
      "name": "District type",
      "description": "Label for DOC: the type of district/agency operating the school (Unified School District, Elementary School District, County Office of Education, High School District, ROC/P, JPA, Community College District, Non-School Locations, etc.).",
      "status": "resolved"
    },
    "District": {
      "role": "identifier",
      "name": "District name",
      "description": "Name of the district or administering agency (district, county office of education, JPA, etc.) that operates the school.",
      "status": "resolved"
    },
    "EILCode": {
      "role": "identifier",
      "name": "Instructional level code (EIL)",
      "description": "CDE Educational Instruction Level code for the school; pairs 1:1 with EILName (ELEM = Elementary, HS = High School, UG = Ungraded, INTMIDJR = Intermediate/Middle/Junior High, ELEMHIGH = Elementary-High Combination, A = Adult, PS = Preschool).",
      "status": "resolved"
    },
    "EILName": {
      "role": "identifier",
      "name": "Instructional level",
      "description": "Label for EILCode: the school's instructional level (Elementary, High School, Ungraded, Intermediate/Middle/Junior High, Elementary-High Combination, Adult, Preschool).",
      "status": "resolved"
    },
    "EdOpsCode": {
      "role": "identifier",
      "name": "Educational options code",
      "description": "CDE Educational Options code: the school's program type; pairs 1:1 with EdOpsName (TRAD = Traditional, CON = Continuation School, COMMDAY = Community Day School, ALTSOC = Alternative School of Choice, SPEC = Special Education School, ROP = Regional Occupational Program, YTH = Youth Authority, HOMHOS = Home & Hospital, JUV = Juvenile Court School). Null for ~32% of rows.",
      "status": "resolved"
    },
    "EdOpsName": {
      "role": "identifier",
      "name": "Educational options type",
      "description": "Label for EdOpsCode (Traditional, Continuation School, Community Day School, Alternative School of Choice, Special Education School, Opportunity School, Juvenile Court School, State Special School, Home and Hospital, etc.).",
      "status": "resolved"
    },
    "Ext": {
      "role": "identifier",
      "name": "Phone extension",
      "description": "Telephone extension for the school's main phone number (Phone); mostly 3-4 digit values, null for ~97% of rows. A few outliers (e.g. 630100) look like data-entry errors.",
      "status": "resolved"
    },
    "FundingType": {
      "role": "identifier",
      "name": "Charter funding type",
      "description": "How a charter school is funded: 'Directly funded' (receives state funds directly) vs 'Locally funded' (funded through its authorizing district); 'Not in CS funding model' for rows outside the charter-school funding model. Populated only for charter schools.",
      "status": "resolved"
    },
    "GSoffered": {
      "role": "identifier",
      "name": "Grades offered",
      "description": "Span of grade levels the school offers, as lowest-highest (e.g. K-5, 9-12, K-8); single grades (e.g. '10') and 'P' (preschool) also occur. Null for ~22% of rows.",
      "status": "resolved"
    },
    "GSserved": {
      "role": "identifier",
      "name": "Grades served",
      "description": "Span of grade levels the school actually serves (lowest-highest, e.g. K-5, 6-8); can differ from GSoffered. Null for ~33% of rows.",
      "status": "resolved"
    },
    "LastUpdate": {
      "role": "identifier",
      "name": "Last update date",
      "description": "Date the directory record was last updated (1999-06-24 to 2016-10-12); the 1999-06-24 spike (3,201 rows) reflects a bulk load of older records.",
      "status": "resolved"
    },
    "Latitude": {
      "role": "identifier",
      "name": "Latitude",
      "description": "Latitude of the school's physical location in decimal degrees (all values within California, ~32.5 to 44.2 N); null for ~27% of rows.",
      "status": "resolved"
    },
    "Longitude": {
      "role": "identifier",
      "name": "Longitude",
      "description": "Longitude of the school's physical location in decimal degrees (negative, ~-124.3 to -83.8); null for ~27% of rows.",
      "status": "resolved"
    },
    "Magnet": {
      "role": "identifier",
      "name": "Magnet school flag",
      "description": "1 = the school is a magnet school, 0 = not; null (~40%) where not reported.",
      "status": "resolved"
    },
    "MailCity": {
      "role": "identifier",
      "name": "Mailing address city",
      "description": "City of the school's mailing address (pairs with MailStreet/MailState/MailZip).",
      "status": "resolved"
    },
    "MailState": {
      "role": "identifier",
      "name": "Mailing address state",
      "description": "State of the mailing address; always 'CA'.",
      "status": "resolved"
    },
    "MailStrAbr": {
      "role": "identifier",
      "name": "Mailing street (abbreviated)",
      "description": "Mailing street address with abbreviated street/suite designations ('Ave.', 'Dr.', 'Ste.'); same address as MailStreet.",
      "status": "resolved"
    },
    "MailStreet": {
      "role": "identifier",
      "name": "Mailing street",
      "description": "Mailing street address with spelled-out designations ('Avenue', 'Drive', 'Suite').",
      "status": "resolved"
    },
    "MailZip": {
      "role": "identifier",
      "name": "Mailing ZIP code",
      "description": "ZIP code (often ZIP+4) of the school's mailing address.",
      "status": "resolved"
    },
    "NCESDist": {
      "role": "identifier",
      "name": "NCES district ID",
      "description": "7-digit federal NCES local education agency (district) identifier: '06' (California FIPS code) + 5-digit district number; shared by all schools in a district (e.g. 0622710 = Los Angeles Unified, 1,342 rows).",
      "status": "resolved"
    },
    "NCESSchool": {
      "role": "identifier",
      "name": "NCES school ID",
      "description": "5-digit NCES school identifier (unique within a district); null for ~29% of rows (district-level or unassigned records).",
      "status": "resolved"
    },
    "OpenDate": {
      "role": "identifier",
      "name": "Opening date",
      "description": "Date the school opened (1850 to 2017); 1980-07-01 for 10,679 rows appears to be a default for schools predating the directory's records.",
      "status": "resolved"
    },
    "Phone": {
      "role": "identifier",
      "name": "Phone number",
      "description": "School's main phone number, formatted '(XXX) XXX-XXXX'; null for ~34% of rows.",
      "status": "resolved"
    },
    "SOC": {
      "role": "identifier",
      "name": "School type code (SOC)",
      "description": "Two-digit CDE code classifying the school's type/category; pairs 1:1 with SOCType (60 = Elementary Schools (Public), 66 = High Schools (Public), 62 = Intermediate/Middle Schools (Public), 68 = Continuation High Schools, 09 = Special Education Schools (Public), 08 = Preschool, 70 = Adult Education Centers).",
      "status": "resolved"
    },
    "SOCType": {
      "role": "identifier",
      "name": "School type",
      "description": "Label for SOC: the school's category (Elementary Schools (Public), High Schools (Public), Intermediate/Middle Schools (Public), Continuation High Schools, Special Education Schools (Public), Adult Education Centers, Alternative Schools of Choice, Junior High Schools (Public), etc.).",
      "status": "resolved"
    },
    "School": {
      "role": "identifier",
      "name": "School name",
      "description": "Name of the school (e.g. 'Lincoln Elementary'); null for ~8% of rows (district-level records).",
      "status": "resolved"
    },
    "State": {
      "role": "identifier",
      "name": "Physical address state",
      "description": "State of the school's physical location; always 'CA' (California).",
      "status": "resolved"
    },
    "StatusType": {
      "role": "identifier",
      "name": "Administrative status",
      "description": "CDE administrative status of the school: Active (11,708), Closed (4,518), Merged (1,448) or Pending (12).",
      "status": "resolved"
    },
    "Street": {
      "role": "identifier",
      "name": "Physical street address",
      "description": "Street of the school's physical location with spelled-out street types ('Road', 'Street').",
      "status": "resolved"
    },
    "StreetAbr": {
      "role": "identifier",
      "name": "Physical street address (abbreviated)",
      "description": "Street of the school's physical location with abbreviated street types ('Rd.', 'St.'); same address as Street.",
      "status": "resolved"
    },
    "Virtual": {
      "role": "identifier",
      "name": "Virtual instruction flag",
      "description": "Three-valued flag that appears to indicate virtual/online schooling: N = not virtual (9,703), P = partially/primarily virtual (1,046), F = fully virtual (69); null for ~39% of rows. The name and value pattern support this reading, but the exact code definitions are unverified - an alternative would be that P and F distinguish the degree of online instruction differently (e.g. 'primarily' vs 'fully' face-to-face vs online).",
      "status": "tentative"
    },
    "Website": {
      "role": "identifier",
      "name": "Website URL",
      "description": "School's or its district's website URL (frequently the district site, e.g. www.fusd.net); null for ~61% of rows.",
      "status": "resolved"
    },
    "Zip": {
      "role": "identifier",
      "name": "Physical address ZIP code",
      "description": "ZIP code (often ZIP+4) of the school's physical location.",
      "status": "resolved"
    }
  }
}
